#include <iostream>
#include <string>

class OC {
public:
    std::string name;
    std::string explain;

    OC(std::string n, std::string e) : name(n), explain(e) {}

    void display() {
        std::cout << "君子曰: \"" << explain << "\"\n";
    }
};

int main() {
    OC *oc = new OC("名人", "虹乃日光雨露之際，光分七色也。");
    oc->display();
    delete oc;
    return 0;
}
